    from hit where last_head is not null
), ok as (
  select count(*) = 476 and coalesce(bool_and(md5(new_outcomes::text) = after_fp
                                              and jsonb_array_length(new_outcomes) > 0), false) as go
    from fixed
), done as (
  update public.course_outcomes c
     set lead = f.new_lead,
         outcomes = f.new_outcomes,
         shape = case when jsonb_array_length(f.new_outcomes) > 1 then 'list' else 'paragraph' end,
         fingerprint = md5(f.new_outcomes::text)
    from fixed f, ok
   where c.id = f.id and ok.go
  returning c.id, c.fingerprint as after_fingerprint
)
select json_build_object(
  'at', to_char(now() at time zone 'utc', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
  'updated', (select count(*) from done),
  'eligible', (select count(*) from fixed),
  'refused', not (select go from ok),
  'mismatch', coalesce((select json_agg(d.id order by d.id) from done d join e using (id)
                         where d.after_fingerprint <> e.after_fp), '[]'::json),
  'checksum', (select md5(string_agg(id || ':' || after_fingerprint, ',' order by id)) from done),
  'rows', coalesce((select json_agg(json_build_array(id, after_fingerprint) order by id) from done), '[]'::json));
